SELECT N'vf.Subtitles' AS TableName,COUNT_BIG(*) AS RowsCount,CHECKSUM_AGG(BINARY_CHECKSUM([SubtitleId],[ProjectId],[VoiceGenerationId],[Version],[Format],[LanguageCode],[StyleJson],[MediaAssetId],[Status],[CreatedAtUtc],[RowVersion])) AS ContentChecksum FROM [vf].[Subtitles];
SELECT N'vf.UsageCosts' AS TableName,COUNT_BIG(*) AS RowsCount,CHECKSUM_AGG(BINARY_CHECKSUM([UsageCostId],[ProjectId],[SceneId],[JobId],[ProviderRequestId],[UsageKey],[CostKind],[ProviderCode],[ModelCode],[UsageType],[Quantity],[Unit],[UnitPrice],[TotalCost],[CurrencyCode],[RateSnapshotJson],[OccurredAtUtc],[CreatedAtUtc])) AS ContentChecksum FROM [vf].[UsageCosts];
SELECT N'vf.VideoGenerations' AS TableName,COUNT_BIG(*) AS RowsCount,CHECKSUM_AGG(BINARY_CHECKSUM([VideoGenerationId],[SceneId],[ScenePromptId],[JobId],[ProviderRequestId],[AttemptNumber],[Status],[Seed],[RequestedDurationMs],[ActualDurationMs],[InputReferenceAssetIdsJson],[OutputMediaAssetId],[QualityScore],[QualityReportJson],[RegenerationFeedbackJson],[CreatedAtUtc],[CompletedAtUtc],[RowVersion])) AS ContentChecksum FROM [vf].[VideoGenerations];
SELECT N'vf.VoiceGenerations' AS TableName,COUNT_BIG(*) AS RowsCount,CHECKSUM_AGG(BINARY_CHECKSUM([VoiceGenerationId],[ProjectId],[ScriptId],[ProviderRequestId],[Version],[VoiceCode],[LanguageCode],[SpeakingRate],[Status],[DurationMs],[WordTimingsJson],[OutputMediaAssetId],[CreatedAtUtc],[CompletedAtUtc],[RowVersion],[SceneId],[ScenePlanVersion],[NarrationHash],[ProviderVoiceCode],[VoiceSnapshotJson],[VoiceSnapshotHash],[VoiceProfileVersionId],[VerificationStatus],[ApprovedAtUtc])) AS ContentChecksum FROM [vf].[VoiceGenerations];
SELECT N'vf.VoiceProfiles' AS TableName,COUNT_BIG(*) AS RowsCount,CHECKSUM_AGG(BINARY_CHECKSUM([VoiceProfileId],[ProjectId],[Scope],[CharacterId],[CreatedAtUtc],[RowVersion])) AS ContentChecksum FROM [vf].[VoiceProfiles];
SELECT N'vf.VoiceProfileVersions' AS TableName,COUNT_BIG(*) AS RowsCount,CHECKSUM_AGG(BINARY_CHECKSUM([VoiceProfileVersionId],[VoiceProfileId],[Version],[ProviderCode],[ModelCode],[VoiceCode],[ProviderVoiceCode],[LanguageCode],[SpeakingRate],[VoiceInstructions],[SnapshotHash],[Status],[CreatedAtUtc],[ApprovedAtUtc],[SupersededAtUtc],[RowVersion],[PreviewProviderRequestId],[PreviewSha256],[PreviewDurationMs],[PreviewExpiresAtUtc],[ApprovedByUserId])) AS ContentChecksum FROM [vf].[VoiceProfileVersions];
SELECT N'vs.Projects' AS TableName,COUNT_BIG(*) AS RowsCount,CHECKSUM_AGG(BINARY_CHECKSUM([ProjectId],[OrganizationId],[CreatedByUserId],[Name],[Status],[SourceLanguageCode],[TargetLanguageCode],[IsArchived],[CreatedAtUtc],[UpdatedAtUtc],[ArchivedAtUtc],[RowVersion])) AS ContentChecksum FROM [vs].[Projects];